 @Id private String id; private String customerUserId; private String customerName; private String customerPhone; private String categoryCode; private String categoryLabel; private String subcategoryCode; private String subcategoryLabel; private String stateCode; private String stateLabel; private String cityCode; private String cityLabel; private String pincode; private String address; private String description; private String preferredContact; private String status="REQUESTED"; private Instant createdAt=Instant.now();
 public String getId(){return id;}public void setId(String v){id=v;}public String getCustomerUserId(){return customerUserId;}public void setCustomerUserId(String v){customerUserId=v;}public String getCustomerName(){return customerName;}public void setCustomerName(String v){customerName=v;}public String getCustomerPhone(){return customerPhone;}public void setCustomerPhone(String v){customerPhone=v;}public String getCategoryCode(){return categoryCode;}public void setCategoryCode(String v){categoryCode=v;}public String getCategoryLabel(){return categoryLabel;}public void setCategoryLabel(String v){categoryLabel=v;}public String getSubcategoryCode(){return subcategoryCode;}public void setSubcategoryCode(String v){subcategoryCode=v;}public String getSubcategoryLabel(){return subcategoryLabel;}public void setSubcategoryLabel(String v){subcategoryLabel=v;}public String getStateCode(){return stateCode;}public void setStateCode(String v){stateCode=v;}public String getStateLabel(){return stateLabel;}public void setStateLabel(String v){stateLabel=v;}public String getCityCode(){return cityCode;}public void setCityCode(String v){cityCode=v;}public String getCityLabel(){return cityLabel;}public void setCityLabel(String v){cityLabel=v;}public String getPincode(){return pincode;}public void setPincode(String v){pincode=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}public String getPreferredContact(){return preferredContact;}public void setPreferredContact(String v){preferredContact=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public Instant getCreatedAt(){return createdAt;}public void setCreatedAt(Instant v){createdAt=v;}
